package com.aistudio.zipspeed.zskt;
import android.app.Activity;import android.net.Uri;import android.os.Build;import android.os.Bundle;import android.webkit.MimeTypeMap;import android.webkit.WebResourceRequest;import android.webkit.WebResourceResponse;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;import java.io.IOException;import java.io.InputStream;
public class MainActivity extends Activity{
private WebView webView;
@Override protected void onCreate(Bundle state){super.onCreate(state);webView=new WebView(this);WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);s.setSaveFormData(false);s.setSupportMultipleWindows(false);if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.LOLLIPOP)s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.O)s.setSafeBrowsingEnabled(true);webView.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri uri=request.getUrl();return!("https".equals(uri.getScheme())&&"appassets.androidplatform.net".equals(uri.getHost()));}@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){Uri uri=request.getUrl();if("https".equals(uri.getScheme())&&"appassets.androidplatform.net".equals(uri.getHost())){String p=uri.getPath();if(p!=null&&p.startsWith("/assets/")){String asset=p.substring("/assets/".length());try{InputStream in=getAssets().open(asset);String ext=MimeTypeMap.getFileExtensionFromUrl(asset),mime=MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext);if(mime==null)mime=asset.endsWith(".mjs")?"text/javascript":asset.endsWith(".css")?"text/css":"application/octet-stream";return new WebResourceResponse(mime,"UTF-8",in);}catch(IOException ignored){return null;}}}return super.shouldInterceptRequest(view,request);}});setContentView(webView);webView.loadUrl("https://appassets.androidplatform.net/assets/index.html");}
@Override protected void onStop(){if(webView!=null)webView.evaluateJavascript("document.dispatchEvent(new Event('visibilitychange'))",null);super.onStop();}
@Override protected void onDestroy(){if(webView!=null){webView.destroy();webView=null;}super.onDestroy();}
}
